mapper.select:
SELECT ledger_no AS ledgerNo, account_no AS accountNo, biz_type AS bizType, biz_no AS bizNo, FORMAT(amount, 2) AS amount, direction, DATE_FORMAT(created_at, '%Y-%m-%d %H:%i:%s') AS createdAt FROM t_wallet_ledger
account_no = #{accountNo}
AND biz_type = #{bizType}
AND direction = #{direction}
ORDER BY created_at DESC

mapper.update:
UPDATE t_wallet_account
SET available_amount = available_amount + #{amount}
WHERE account_no = #{accountNo}

UPDATE t_wallet_red_packet
SET status = #{status}
WHERE red_packet_no = #{redPacketNo}
